{
  "overview": "A lightweight, secure, and persistent URL shortener service built with Python 3.11+, FastAPI, and standard-library sqlite3. The system supports short link creation with optional custom aliases, UTC expiration handling, HTTP 302 redirection, persistent click analytics, SSRF destination validation, sliding-window rate limiting, and structured JSON logging.",
  "components": [
    {
      "name": "Configuration",
      "module": "app/config.py",
      "responsibility": "Loads and validates environment variables (DATABASE_PATH, BASE_URL, RATE_LIMIT_REQUESTS, RATE_LIMIT_WINDOW_SECONDS, LOG_LEVEL) using Pydantic Settings."
    },
    {
      "name": "Database Layer",
      "module": "app/database.py",
      "responsibility": "Initializes SQLite schema, WAL journal mode, manages thread-safe sqlite3 connection pools/contexts, and executes data access queries."
    },
    {
      "name": "Validation & Security",
      "module": "app/security.py",
      "responsibility": "Performs SSRF validation against requested target URLs (ensures HTTP/HTTPS scheme and verifies resolved IP addresses are not private, loopback, link-local, multicast, or reserved ranges)."
    },
    {
      "name": "Rate Limiter",
      "module": "app/rate_limiter.py",
      "responsibility": "Enforces in-memory sliding window or token rate limiting per client IP address, emitting 429 Too Many Requests and Retry-After headers."
    },
    {
      "name": "Link Service",
      "module": "app/service.py",
      "responsibility": "Coordinates code generation (Base62), custom alias checks, link creation, expiration checks, redirection lookups, and analytics tracking."
    },
    {
      "name": "Schemas",
      "module": "app/schemas.py",
      "responsibility": "Defines Pydantic request and response models for short link creation, responses, analytics, and health status."
    },
    {
      "name": "Middleware & Logging",
      "module": "app/logging.py",
      "responsibility": "Configures structured JSON logging and provides ASGI middleware emitting request metadata, status code, latency, and exception traces."
    },
    {
      "name": "API Entrypoint & Routers",
      "module": "app/main.py",
      "responsibility": "Assembles the FastAPI application, mounts middlewares, registers lifecycle hooks for database initialization, and exposes HTTP route handlers."
    }
  ],
  "api": [
    {
      "method": "POST",
      "path": "/shorten",
      "summary": "Create a new shortened link with optional alias and expiration time.",
      "status_codes": [201, 400, 409, 429, 500],
      "requirement_ids": ["R1", "R5", "R6", "R7"]
    },
    {
      "method": "GET",
      "path": "/{code}",
      "summary": "Redirect caller to original target URL if valid and not expired, incrementing analytics counter.",
      "status_codes": [302, 404, 500],
      "requirement_ids": ["R2", "R7"]
    },
    {
      "method": "GET",
      "path": "/analytics/{code}",
      "summary": "Retrieve link usage statistics including total clicks, created timestamp, and last visited timestamp.",
      "status_codes": [200, 404, 500],
      "requirement_ids": ["R3", "R7"]
    },
    {
      "method": "GET",
      "path": "/health",
      "summary": "Check service and SQLite database operational status for health monitors.",
      "status_codes": [200, 503],
      "requirement_ids": ["R4"]
    }
  ],
  "data_model": [
    {
      "name": "ShortLink",
      "fields": [
        "id: INTEGER PRIMARY KEY AUTOINCREMENT",
        "code: TEXT UNIQUE NOT NULL",
        "original_url: TEXT NOT NULL",
        "created_at: TEXT NOT NULL (ISO 8601 UTC timestamp)",
        "expires_at: TEXT NULL (ISO 8601 UTC timestamp)",
        "total_clicks: INTEGER NOT NULL DEFAULT 0",
        "last_visited_at: TEXT NULL (ISO 8601 UTC timestamp)"
      ]
    }
  ],
  "decisions": [
    {
      "id": "D1",
      "title": "Use SQLite WAL mode with standard library sqlite3",
      "choice": "Use sqlite3 standard library with WAL (Write-Ahead Logging) mode and connection per-request context manager.",
      "rationale": "Meets technology constraints without introducing heavy external ORMs while providing concurrent reads and reliable persistence across restarts.",
      "alternatives": ["SQLAlchemy with SQLite", "In-memory dictionary with JSON file dumps"]
    },
    {
      "id": "D2",
      "title": "HTTP 302 Found for Redirection",
      "choice": "Return HTTP 302 Found for GET /{code}.",
      "rationale": "Prevents client browsers from aggressively caching the redirect target, guaranteeing that subsequent clicks hit the backend to increment analytics accurately.",
      "alternatives": ["HTTP 301 Moved Permanently", "HTTP 307 Temporary Redirect"]
    },
    {
      "id": "D3",
      "title": "Synchronous DNS resolution with IP address validation for SSRF defense",
      "choice": "Use socket.getaddrinfo and ipaddress.ip_address to reject private, loopback, link-local, multicast, and non-global IPs before accepting URLs.",
      "rationale": "Protects internal network perimeters against SSRF attacks directly in app/security.py without relying on external security agents.",
      "alternatives": ["Regex matching on hostnames only", "Proxying all outbound requests through an egress firewall"]
    },
    {
      "id": "D4",
      "title": "In-memory sliding window rate limiter",
      "choice": "Implement an in-memory sliding window rate limiter keyed by client IP address.",
      "rationale": "Simplifies deployment architecture without introducing Redis dependencies while fulfilling single-instance rate-limiting constraints.",
      "alternatives": ["External Redis rate limiting", "Fixed-window counter with coarse reset"]
    }
  ],
  "risks": [
    {
      "risk": "DNS rebinding / TOCTOU SSRF attacks where a domain resolves to a public IP during validation but later to an internal IP.",
      "mitigation": "Perform strict IP validation upon creation; since this service issues HTTP 302 redirects without fetching content internally, the primary SSRF vector is redirecting internal users/browsers to intranet services. Restrict loopback, metadata (169.254.169.254), and RFC1918 addresses at creation time."
    },
    {
      "risk": "High concurrency SQLite database locked errors (busy errors) under concurrent click redirects.",
      "mitigation": "Enable WAL mode (`PRAGMA journal_mode=WAL`), set `PRAGMA busy_timeout=5000`, and use atomic SQL updates (`UPDATE urls SET total_clicks = total_clicks + 1, last_visited_at = ? WHERE code = ?`)."
    },
    {
      "risk": "Generated Base62 code collisions over time.",
      "mitigation": "Generate random 7-character Base62 codes with up to 5 retries upon unique constraint collision in SQLite before failing."
    }
  ],
  "tasks": [
    {
      "id": "T1",
      "title": "Implement configuration module and environment variable parser in app/config.py",
      "owner": "developer",
      "requirement_ids": ["R1", "R4", "R6", "R7"],
      "depends_on": []
    },
    {
      "id": "T2",
      "title": "Implement SQLite database schema initialization and connection context manager in app/database.py",
      "owner": "developer",
      "requirement_ids": ["R1", "R2", "R3", "R4", "R7"],
      "depends_on": ["T1"]
    },
    {
      "id": "T3",
      "title": "Implement Pydantic schemas in app/schemas.py",
      "owner": "developer",
      "requirement_ids": ["R1", "R3", "R4"],
      "depends_on": ["T1"]
    },
    {
      "id": "T4",
      "title": "Implement SSRF URL validation in app/security.py",
      "owner": "developer",
      "requirement_ids": ["R5"],
      "depends_on": ["T1"]
    },
    {
      "id": "T5",
      "title": "Implement in-memory sliding window rate limiter in app/rate_limiter.py",
      "owner": "developer",
      "requirement_ids": ["R6"],
      "depends_on": ["T1"]
    },
    {
      "id": "T6",
      "title": "Implement structured JSON logging and latency ASGI middleware in app/logging.py",
      "owner": "developer",
      "requirement_ids": ["R8"],
      "depends_on": ["T1"]
    },
    {
      "id": "T7",
      "title": "Implement business logic and code generation in app/service.py",
      "owner": "developer",
      "requirement_ids": ["R1", "R2", "R3", "R5", "R7"],
      "depends_on": ["T2", "T3", "T4"]
    },
    {
      "id": "T8",
      "title": "Implement FastAPI application routes and handlers in app/main.py",
      "owner": "developer",
      "requirement_ids": ["R1", "R2", "R3", "R4", "R5", "R6", "R8"],
      "depends_on": ["T5", "T6", "T7"]
    },
    {
      "id": "T9",
      "title": "Write unit tests for SSRF validation, Base62 generation, and rate limiting in tests/test_security_and_utils.py",
      "owner": "tester",
      "requirement_ids": ["R5", "R6", "R9"],
      "depends_on": ["T4", "T5"]
    },
    {
      "id": "T10",
      "title": "Write integration test suite for /shorten, /{code}, /analytics/{code}, and /health endpoints in tests/test_api.py",
      "owner": "tester",
      "requirement_ids": ["R1", "R2", "R3", "R4", "R5", "R6", "R7", "R9"],
      "depends_on": ["T8"]
    },
    {
      "id": "T11",
      "title": "Write persistence across restart tests in tests/test_persistence.py",
      "owner": "tester",
      "requirement_ids": ["R7", "R9"],
      "depends_on": ["T8"]
    },
    {
      "id": "T12",
      "title": "Author API documentation and setup guide in README.md",
      "owner": "docs",
      "requirement_ids": ["R1", "R2", "R3", "R4", "R5", "R6", "R8"],
      "depends_on": ["T8"]
    }
  ]
}
